/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Exports
 *   Types: LoginDraft
 *   Functions: researchReadiness, ResearchReadiness
 * Internal
 *   Types: Props
 * @end-catalog */

import {KeyboardEvent, useEffect, useRef, useState} from 'react';
import {BookOpen, CircleAlert, CircleCheck, KeyRound, LoaderCircle, MonitorCog, RefreshCw, Unplug} from 'lucide-react';
import {AppSettings, ChromeConnectionStatus} from '../types';
import {LOGIN_URL} from '../browser/auth';
import {isExtensionOutdated, latestExtensionVersion} from '../browser/extensionVersion';

/** The in-progress Archtree sign-in; the parent keeps it so it survives this panel unmounting in demo mode. */
export interface LoginDraft {
  identifier: string;
  error: string;
  busy: boolean;
}

/** What live research still needs; the new-research form and this panel read the same answer. */
export const researchReadiness = (settings: AppSettings, chromeStatus?: ChromeConnectionStatus) => {
  const browserRuntime = settings.runtime === 'browser';
  const analysis = settings.analysis;
  const aiReady = Boolean(analysis?.aiConfigured);
  // A valid account stays signed in when the server's AI service is unavailable.
  const analysisUnavailable = analysis?.transport === 'proxy' && Boolean(analysis.account)
    && !analysis.loginRequired && !analysis.aiConfigured;
  const chromeTransitioning = chromeStatus?.state === 'connecting' || chromeStatus?.state === 'disconnecting';
  const chromeReady = chromeStatus?.state === 'connected'
    && chromeStatus.connected
    && chromeStatus.loginState === 'logged_in';
  // 'not_ready' means the extension never answered, so there is no installed version to compare.
  const extensionOutdated = browserRuntime && chromeStatus !== undefined && chromeStatus.state !== 'not_ready'
    && isExtensionOutdated(chromeStatus.extensionVersion);
  const aiStep = analysis?.transport === 'direct' ? '配置 OpenAI API 密钥'
    : analysisUnavailable ? '等待 AI 分析服务恢复' : '登录 Archtree';
  const chromeStep = browserRuntime ? '连接 B站采集扩展' : '连接 Chrome 并登录 B站';
  const pendingSteps = [!aiReady && aiStep, !chromeReady && chromeStep].filter((step): step is string => Boolean(step));
  // Something the user can act on now; an unavailable AI service only needs waiting.
  const actionable = !chromeReady || (!aiReady && !analysisUnavailable);
  return {browserRuntime, aiReady, analysisUnavailable, chromeReady, chromeTransitioning, extensionOutdated, pendingSteps, actionable};
};

interface Props {
  settings: AppSettings;
  chromeStatus?: ChromeConnectionStatus;
  connectingChrome: boolean;
  login: LoginDraft;
  onLoginChange: (change: Partial<LoginDraft>) => void;
  onLoginAnalysis?: (identifier: string, password: string) => Promise<void>;
  onOpenGuide: () => void;
  onConnectChrome: () => Promise<void>;
  onDisconnectChrome: () => Promise<void>;
}

export const ResearchReadiness = ({
  settings,
  chromeStatus,
  connectingChrome,
  login: {identifier, error: authenticationError, busy: authenticating},
  onLoginChange,
  onLoginAnalysis,
  onOpenGuide,
  onConnectChrome,
  onDisconnectChrome
}: Props) => {
  const [password, setPassword] = useState('');
  const chromeItem = useRef<HTMLLIElement>(null);
  const restoreChromeFocus = useRef(false);
  const {browserRuntime, aiReady, analysisUnavailable, chromeReady, extensionOutdated, ...readiness} = researchReadiness(settings, chromeStatus);
  const chromeTransitioning = connectingChrome || readiness.chromeTransitioning;
  const analysis = settings.analysis;
  const loginRequired = analysis?.transport === 'proxy' && analysis.loginRequired;
  const account = analysis?.transport === 'proxy' ? analysis.account : undefined;
  const completed = [aiReady, chromeReady].filter(Boolean).length;
  const rechecking = chromeReady && connectingChrome;
  const chromeActionLabel = chromeStatus?.state === 'disconnecting' ? '正在断开 Chrome…'
    : connectingChrome || chromeStatus?.state === 'connecting' ? '等待 Chrome 授权…'
    : browserRuntime ? '连接扩展并检查 B站'
    : !chromeStatus?.remoteDebuggingEnabled ? '开启并连接 Chrome'
    : chromeStatus.connected && chromeStatus.loginState !== 'logged_in' ? '重新检查 B站登录'
    : chromeStatus.connected ? '重新检查连接' : '连接并检查 B站';

  // Connecting, re-checking and disconnecting swap or disable the button that had focus;
  // once the transition settles, hand focus to the first usable control of the B站 step.
  useEffect(() => {
    if (!restoreChromeFocus.current || chromeTransitioning) return;
    restoreChromeFocus.current = false;
    const active = document.activeElement;
    if (active && active !== document.body) return;
    chromeItem.current?.querySelector<HTMLElement>('button:not(:disabled)')?.focus();
  });

  const runChromeAction = (action: () => Promise<void>) => {
    restoreChromeFocus.current = true;
    void action();
  };

  const login = async () => {
    if (authenticating || !identifier.trim() || !password) return;
    onLoginChange({busy: true, error: ''});
    try {
      if (!onLoginAnalysis) throw new Error('当前版本不支持 Archtree 登录。');
      await onLoginAnalysis(identifier, password);
      setPassword('');
      onLoginChange({busy: false});
    } catch (error) {
      onLoginChange({busy: false, error: error instanceof Error ? error.message : String(error)});
    }
  };

  // The login fields sit inside the research form; Enter signs in instead of submitting the research.
  const loginOnEnter = (event: KeyboardEvent<HTMLInputElement>) => {
    if (event.key !== 'Enter') return;
    event.preventDefault();
    void login();
  };

  const aiItem = aiReady ? {
    state: 'done',
    title: account ? '已登录 Archtree' : 'AI 分析已就绪',
    detail: account ? `${account.email} · 登录有效` : 'OpenAI API 密钥已配置'
  } : analysisUnavailable ? {
    state: 'warning',
    title: '已登录 Archtree',
    detail: `${account?.email} · 登录有效`
  } : analysis?.transport === 'direct' ? {
    state: 'todo',
    title: '需要配置 OpenAI API 密钥',
    detail: '桌面版在配置文件中设置密钥后重新启动工具。'
  } : {
    state: 'todo',
    title: '登录 Archtree 后使用 AI 分析',
    detail: browserRuntime ? '使用任意普通 Archtree 账号，登录后会回到此页。'
      : '任意普通 Archtree 账号即可；密码不会保存，OpenAI 密钥也不会进入这台电脑。'
  };

  return (
    <section className="readiness" id="research-readiness" tabIndex={-1} aria-labelledby="readiness-title">
      <div className="readiness-heading">
        <h2 id="readiness-title">开始前准备</h2>
        <span>{completed}/2 已完成</span>
      </div>
      <ol className="readiness-list">
        <li className={`readiness-item ${aiItem.state}`}>
          <span className="readiness-icon" aria-hidden="true">{aiItem.state === 'done' ? <CircleCheck size={18}/> : aiItem.state === 'warning' ? <CircleAlert size={18}/> : <KeyRound size={18}/>}</span>
          <div className="readiness-body">
            <strong>{aiItem.title}</strong>
            <small>{aiItem.detail}</small>
            {analysisUnavailable && <p className="readiness-warning" role="status">AI 分析服务暂不可用，请稍后重试。</p>}
            {loginRequired && (browserRuntime
              ? <a className="readiness-action" href={LOGIN_URL}>前往 Archtree 登录</a>
              : <div className="readiness-login">
                <input id="archtree-identifier" aria-label="Archtree 邮箱或用户名" autoComplete="username" value={identifier} onChange={(event) => onLoginChange({identifier: event.target.value})} onKeyDown={loginOnEnter} placeholder="邮箱或用户名"/>
                <input aria-label="Archtree 密码" type="password" autoComplete="current-password" value={password} onChange={(event) => setPassword(event.target.value)} onKeyDown={loginOnEnter} placeholder="密码"/>
                <button className="readiness-action" type="button" disabled={authenticating || !identifier.trim() || !password} onClick={() => void login()}>
                  {authenticating ? <LoaderCircle className="spin" size={16}/> : <KeyRound size={16}/>} {authenticating ? '正在登录…' : '登录'}
                </button>
              </div>)}
            {authenticationError && <p className="readiness-warning" role="alert">{authenticationError}</p>}
          </div>
        </li>
        <li className={`readiness-item ${chromeReady ? 'done' : 'todo'}`} ref={chromeItem}>
          <span className="readiness-icon" aria-hidden="true">{chromeReady ? <CircleCheck size={18}/> : <MonitorCog size={18}/>}</span>
          <div className="readiness-body">
            <strong>{chromeReady ? '已连接 B站账号' : browserRuntime ? '连接 B站采集扩展' : '连接已经登录 B站的 Chrome'}</strong>
            <small>{chromeReady
              ? `${chromeStatus?.accountName ?? '当前账号'}${chromeStatus?.accountUidSuffix ? ` · UID 尾号 ${chromeStatus.accountUidSuffix}` : ''}`
              : chromeStatus?.message ?? '正在检测 Chrome…'}</small>
            {extensionOutdated && <p className="readiness-warning" role="alert">
              {chromeStatus?.extensionVersion ? `当前扩展 ${chromeStatus.extensionVersion} 不是最新版本` : '无法确认当前扩展版本'}，最新版本为 {latestExtensionVersion}。请打开图文教程下载新版，替换原扩展文件夹内容，在 Chrome 扩展管理页点击“重新加载”后刷新此页面。
            </p>}
            <div className="readiness-actions">
              {!chromeReady && <button className="readiness-action" type="button" disabled={chromeTransitioning} onClick={() => runChromeAction(onConnectChrome)}>
                {chromeTransitioning ? <LoaderCircle className="spin" size={16}/> : <MonitorCog size={16}/>} {chromeActionLabel}
              </button>}
              {chromeReady && !browserRuntime && <button className="readiness-link" type="button" disabled={chromeTransitioning} onClick={() => runChromeAction(onConnectChrome)}>{rechecking ? <LoaderCircle className="spin" size={15}/> : <RefreshCw size={15}/>}{rechecking ? '正在检查…' : '重新检查'}</button>}
              <button className="readiness-link" type="button" onClick={onOpenGuide}><BookOpen size={15}/>图文教程</button>
              {chromeStatus?.connected && <button className="readiness-link" type="button" disabled={chromeTransitioning || (chromeStatus.activeInvestigations ?? 0) > 0} onClick={() => runChromeAction(onDisconnectChrome)}><Unplug size={15}/>断开</button>}
            </div>
            {!browserRuntime && <small className="readiness-note">工具只操作自己创建的调查标签页；连接期间请关闭网银、邮箱等敏感页面。</small>}
          </div>
        </li>
      </ol>
    </section>
  );
};
